CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS records(owner INT UNSIGNED NOT NULL,id VARCHAR(100) NOT NULL,kind VARCHAR(20) NOT NULL,data LONGTEXT NOT NULL,updated DATETIME NOT NULL,PRIMARY KEY(owner,id),INDEX(owner,kind)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_scans(owner INT UNSIGNED NOT NULL,id VARCHAR(100) NOT NULL,part VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,PRIMARY KEY(owner,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts(identity CHAR(64) NOT NULL PRIMARY KEY,attempts INT NOT NULL,window_start INT NOT NULL) ENGINE=InnoDB;
